using System.Globalization;
using JellyServer.Configuration;

namespace JellyServer.Transcoding;

/// <summary>
/// "Allow segment deletion", as Jellyfin's TranscodingSegmentCleaner: segments that end more than
/// <see cref="SegmentDeletionOptions.KeepSeconds"/> (at least 20 s) behind the player are deleted. The fMP4 init
/// segment (-1.mp4) and the playlist are never touched; a deleted segment requested again is regenerated by a restart.
/// </summary>
public static class SegmentCleaner
{
    /// <summary>Jellyfin keeps at least this much behind the player.</summary>
    public const int MinKeepSeconds = 20;

    /// <summary>
    /// Jellyfin's rule: highest segment index to delete for a player at <paramref name="positionTicks"/>, or -1 for none.
    /// Index 0 is never deleted by Jellyfin's check (<c>idxMaxToDelete &gt; 0</c>); kept for parity.
    /// </summary>
    public static int MaxIndexToDelete(long positionTicks, int keepSeconds, int segmentSeconds)
    {
        if (segmentSeconds <= 0) return -1;
        var keep = Math.Max(keepSeconds, MinKeepSeconds);
        var position = (long)Math.Round(TimeSpan.FromTicks(Math.Max(positionTicks, 0)).TotalSeconds);
        if (position <= keep) return -1;
        var max = (position - keep) / segmentSeconds;
        return max > 0 ? (int)max : -1;
    }

    /// <summary>Segment indexes in <paramref name="dir"/> with this extension (init segment and temp files excluded).</summary>
    public static IEnumerable<int> Existing(string dir, string extension)
    {
        if (!Directory.Exists(dir)) yield break;
        foreach (var file in Directory.EnumerateFiles(dir, "*." + extension))
        {
            if (int.TryParse(Path.GetFileNameWithoutExtension(file), NumberStyles.None, CultureInfo.InvariantCulture, out var i))
                yield return i;
        }
    }

    /// <summary>
    /// Deletes segments with index ≤ <paramref name="maxIndex"/>; <paramref name="stillDeletable"/> is asked again right
    /// before each file so a request that arrived meanwhile (a seek back) wins. Returns the deleted indexes; files
    /// in use (Windows) are skipped and retried on the next pass.
    /// </summary>
    public static List<int> Delete(string dir, string extension, int maxIndex, Func<int, bool> stillDeletable)
    {
        List<int> deleted = [];
        if (maxIndex < 0) return deleted;
        foreach (var i in Existing(dir, extension).Where(i => i <= maxIndex).Order().ToList())
        {
            if (!stillDeletable(i)) continue;
            try
            {
                File.Delete(Path.Combine(dir, $"{i}.{extension}"));
                deleted.Add(i);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { }
        }
        return deleted;
    }
}
